import type { AppConfig, AutoAnalysisRule } from '../types';

export type LLMGatewayStatusCode = 'checking' | 'available' | 'configured-unavailable' | 'not-configured' | 'error';

export interface LLMGatewayStatus {
  status: LLMGatewayStatusCode;
  title: string;
  message: string;
  checkedAt?: string;
  apiUrl?: string;
  apiPath?: string;
  baseModel?: string;
  largeModel?: string;
  apiKeyConfigured?: boolean;
  healthError?: string;
}

interface WorkerHealthResponse {
  ok?: boolean;
  configured?: boolean;
  title?: string;
  message?: string;
  checkedAt?: string;
  loki?: {
    ok?: boolean;
    baseUrl?: string;
    error?: string;
  };
  litellm?: {
    ok?: boolean;
    configured?: boolean;
    baseUrl?: string;
    model?: string;
    apiKeyConfigured?: boolean;
    error?: string;
  };
}

interface WorkerRulesResponse {
  ok?: boolean;
  rules?: AutoAnalysisRule[];
  rulesPath?: string;
  cachePath?: string;
  runtime?: Record<string, WorkerRuleRuntimeState>;
  savedAt?: string;
  error?: string;
}

export interface WorkerRuleRuntimeState {
  enabled?: boolean;
  triggerSelectionMode?: AutoAnalysisRule['triggerSelectionMode'];
  hasCheckpoint?: boolean;
  lastProcessedTimestampNs?: string;
  lastProcessedTimestamp?: string;
  updatedAt?: string;
  latestMatchedTimestampNs?: string;
  latestMatchedTimestamp?: string;
  latestProbeAt?: string;
  latestProbeError?: string;
  lagSeconds?: number;
  latestRunStatus?: 'running' | 'success' | 'empty' | 'error' | 'failed' | 'timeout' | 'skipped' | '';
  latestRunStartedAt?: string;
  latestRunFinishedAt?: string;
  latestRunDurationMs?: number;
  latestRunError?: string;
  latestRunMessage?: string;
}

export interface WorkerRulesRuntimeOptions {
  ruleIds?: string[];
  probeLatest?: boolean;
  forceProbe?: boolean;
}

export interface WorkerRulesFetchResult {
  rules: AutoAnalysisRule[];
  rulesPath?: string;
  cachePath?: string;
  runtime: Record<string, WorkerRuleRuntimeState>;
}

export interface WorkerRulesSaveResult {
  rules: AutoAnalysisRule[];
  rulesPath?: string;
  savedAt?: string;
}

export interface AlertPayloadField {
  id: string;
  label: string;
  defaultEnabled: boolean;
}

export interface AlertTarget {
  id: string;
  name: string;
  enabled: boolean;
  url: string;
  method: 'POST' | 'PUT' | 'PATCH';
  headers: Record<string, string>;
  timeoutMs: number;
}

export interface AlertBinding {
  id: string;
  name: string;
  enabled: boolean;
  sourceJob?: string;
  logDomain?: string;
  logType?: string;
  ruleIds: string[];
  targetIds: string[];
}

export interface AlertConfig {
  version: number;
  enabled: boolean;
  minSeverity: 'P0' | 'P1' | 'P2' | 'P3' | 'P4';
  triggerLogLimit: number;
  fields: Record<string, boolean>;
  targets: AlertTarget[];
  bindings: AlertBinding[];
}

export interface AlertConfigFetchResult {
  alertConfig: AlertConfig;
  alertConfigPath?: string;
  availableFields: AlertPayloadField[];
}

export interface AlertConfigSaveResult {
  alertConfig: AlertConfig;
  alertConfigPath?: string;
  savedAt?: string;
}

export interface AlertTargetTestResult {
  ok?: boolean;
  reachable?: boolean;
  status?: number | null;
  statusText?: string;
  durationMs?: number;
  responseBody?: string;
  responseBodyTruncated?: boolean;
  responseBodyBytes?: number;
  errorCode?: string;
  error?: string;
  testedAt?: string;
}

interface WorkerAlertConfigResponse {
  ok?: boolean;
  alertConfig?: AlertConfig;
  alertConfigPath?: string;
  availableFields?: AlertPayloadField[];
  savedAt?: string;
  error?: string;
}

const systemPrompt = [
  '你是一个资深 SRE / 游戏服务端故障分析助手。',
  '你需要基于已经脱敏和压缩后的日志证据进行分析。',
  '不要编造不存在的日志证据；不确定时明确写“需要进一步确认”。',
  '输出中文，结构包括：问题概述、影响判断、关键证据、可能原因、排查步骤、临时处置、长期优化。',
].join('\n');

const WORKER_REQUEST_TIMEOUT_MS = 120_000;
const DEFAULT_WORKER_PORT = '18080';

export async function checkLLMGatewayStatus(config?: Pick<AppConfig, 'workerBaseUrl'>): Promise<LLMGatewayStatus> {
  const checkedAt = formatCheckedAt();
  const workerBaseUrl = resolveWorkerBaseUrl(config);

  try {
    const response = await fetchWithTimeout(`${workerBaseUrl}/health`, {
      method: 'GET',
      timeoutMs: 30_000,
    });

    const body = (await safeReadJson(response)) as WorkerHealthResponse;
    if (!response.ok) {
      return {
        status: 'error',
        title: '检查失败',
        message: `worker health 返回 HTTP ${response.status}`,
        checkedAt,
        apiUrl: workerBaseUrl,
        healthError: stringifyError(body),
      };
    }

    return mapWorkerHealthToStatus(body, workerBaseUrl, checkedAt);
  } catch (err) {
    return {
      status: 'error',
      title: '检查失败',
      message: `无法连接 AI worker：${stringifyError(err)}`,
      checkedAt,
      apiUrl: workerBaseUrl,
      healthError: stringifyError(err),
    };
  }
}

export async function runLLMAnalysis(
  prompt: string,
  model?: string,
  config?: Pick<AppConfig, 'workerBaseUrl'>
): Promise<string> {
  const workerBaseUrl = resolveWorkerBaseUrl(config);
  const response = await fetchWithTimeout(`${workerBaseUrl}/analyze`, {
    method: 'POST',
    timeoutMs: WORKER_REQUEST_TIMEOUT_MS,
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      prompt,
      model,
      systemPrompt,
    }),
  });

  const body = (await safeReadJson(response)) as { ok?: boolean; analysis?: string; error?: string };
  if (!response.ok || !body.ok) {
    throw new Error(body.error || `AI worker 分析失败：HTTP ${response.status}`);
  }

  const content = body.analysis?.trim();
  if (!content) {
    throw new Error('AI worker 已返回响应，但没有生成可展示的分析内容。');
  }

  return content;
}

export async function fetchWorkerRules(config?: Pick<AppConfig, 'workerBaseUrl'>): Promise<AutoAnalysisRule[]> {
  const result = await fetchWorkerRulesRuntime(config);
  return result.rules;
}

export async function fetchWorkerRulesRuntime(
  config?: Pick<AppConfig, 'workerBaseUrl'>,
  options?: WorkerRulesRuntimeOptions
): Promise<WorkerRulesFetchResult> {
  const workerBaseUrl = resolveWorkerBaseUrl(config);
  const ruleIds = Array.from(new Set((options?.ruleIds ?? []).map((ruleId) => ruleId.trim()).filter(Boolean)));
  const useRuntimeEndpoint = Boolean(options?.probeLatest || options?.forceProbe || ruleIds.length > 0);
  const params = new URLSearchParams();
  if (ruleIds.length > 0) {
    params.set('ruleIds', ruleIds.join(','));
  }
  if (options?.probeLatest) {
    params.set('probeLatest', 'true');
  }
  if (options?.forceProbe) {
    params.set('forceProbe', 'true');
  }
  const query = params.toString();
  const endpoint = useRuntimeEndpoint ? '/rules/runtime' : '/rules';
  const response = await fetchWithTimeout(`${workerBaseUrl}${endpoint}${query ? `?${query}` : ''}`, {
    method: 'GET',
    timeoutMs: 30_000,
  });

  const body = (await safeReadJson(response)) as WorkerRulesResponse;
  if (!response.ok || !body.ok) {
    throw new Error(body.error || `读取 worker 自动分析规则失败：HTTP ${response.status}`);
  }

  return {
    rules: body.rules ?? [],
    rulesPath: body.rulesPath,
    cachePath: body.cachePath,
    runtime: body.runtime ?? {},
  };
}

export async function saveWorkerRules(
  rules: AutoAnalysisRule[],
  config?: Pick<AppConfig, 'workerBaseUrl'>
): Promise<WorkerRulesSaveResult> {
  const workerBaseUrl = resolveWorkerBaseUrl(config);
  const response = await fetchWithTimeout(`${workerBaseUrl}/rules`, {
    method: 'POST',
    timeoutMs: 30_000,
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ rules }),
  });

  const body = (await safeReadJson(response)) as WorkerRulesResponse;
  if (!response.ok || !body.ok) {
    throw new Error(body.error || `保存 worker 自动分析规则失败：HTTP ${response.status}`);
  }

  return {
    rules: body.rules ?? rules,
    rulesPath: body.rulesPath,
    savedAt: body.savedAt,
  };
}

export async function fetchAlertConfig(config?: Pick<AppConfig, 'workerBaseUrl'>): Promise<AlertConfigFetchResult> {
  const workerBaseUrl = resolveWorkerBaseUrl(config);
  const response = await fetchWithTimeout(`${workerBaseUrl}/alert-config`, {
    method: 'GET',
    timeoutMs: 30_000,
  });

  const body = (await safeReadJson(response)) as WorkerAlertConfigResponse;
  if (!response.ok || !body.ok || !body.alertConfig) {
    throw new Error(body.error || `读取告警平台配置失败：HTTP ${response.status}`);
  }

  return {
    alertConfig: normalizeAlertConfigClient(body.alertConfig, body.availableFields),
    alertConfigPath: body.alertConfigPath,
    availableFields: normalizeAlertFields(body.availableFields),
  };
}

