export async function testAlertTarget(
  target: AlertTarget,
  config?: Pick<AppConfig, 'workerBaseUrl'>
): Promise<AlertTargetTestResult> {
  const workerBaseUrl = resolveWorkerBaseUrl(config);
  const response = await fetchWithTimeout(`${workerBaseUrl}/alert-config/test`, {
    method: 'POST',
    timeoutMs: 35_000,
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ target }),
  });

  const body = (await safeReadJson(response)) as AlertTargetTestResult & { error?: string };
  if (!response.ok) {
    throw new Error(body.error || `告警平台连通性测试失败：HTTP ${response.status}`);
  }

  return body;
}

export function getDefaultWorkerBaseUrl(): string {
  if (typeof window === 'undefined') {
    return `http://localhost:${DEFAULT_WORKER_PORT}`;
  }

  return `${window.location.protocol}//${window.location.hostname}:${DEFAULT_WORKER_PORT}`;
}

function mapWorkerHealthToStatus(body: WorkerHealthResponse, workerBaseUrl: string, checkedAt: string): LLMGatewayStatus {
  const litellm = body.litellm ?? {};
  const loki = body.loki ?? {};
  const healthError = [litellm.error, loki.error].filter(Boolean).join('；') || undefined;

  if (body.ok) {
    return {
      status: 'available',
      title: '可用',
      message: body.message || 'AI worker 已连接 Loki 和 LiteLLM。',
      checkedAt: body.checkedAt ? formatDate(body.checkedAt) : checkedAt,
      apiUrl: litellm.baseUrl || workerBaseUrl,
      apiPath: '/v1',
      baseModel: litellm.model,
      apiKeyConfigured: Boolean(litellm.apiKeyConfigured),
    };
  }

  if (!body.configured || litellm.configured === false) {
    return {
      status: 'not-configured',
      title: '未完成配置',
      message: body.message || 'AI worker 未配置 LiteLLM 地址或 API Key。',
      checkedAt: body.checkedAt ? formatDate(body.checkedAt) : checkedAt,
      apiUrl: litellm.baseUrl || workerBaseUrl,
      apiPath: '/v1',
      baseModel: litellm.model,
      apiKeyConfigured: Boolean(litellm.apiKeyConfigured),
      healthError,
    };
  }

  return {
    status: 'configured-unavailable',
    title: '已配置但不可用',
    message: body.message || 'AI worker 已配置，但 Loki 或 LiteLLM 健康检查未通过。',
    checkedAt: body.checkedAt ? formatDate(body.checkedAt) : checkedAt,
    apiUrl: litellm.baseUrl || workerBaseUrl,
    apiPath: '/v1',
    baseModel: litellm.model,
    apiKeyConfigured: Boolean(litellm.apiKeyConfigured),
    healthError,
  };
}

function resolveWorkerBaseUrl(config?: Pick<AppConfig, 'workerBaseUrl'>): string {
  return trimRightSlash(config?.workerBaseUrl?.trim() || getDefaultWorkerBaseUrl());
}

function trimRightSlash(value: string): string {
  return value.replace(/\/+$/, '');
}

async function fetchWithTimeout(url: string, init: RequestInit & { timeoutMs: number }): Promise<Response> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), init.timeoutMs);
  try {
    const { timeoutMs, ...requestInit } = init;
    return await fetch(url, {
      ...requestInit,
      signal: controller.signal,
    });
  } finally {
    clearTimeout(timer);
  }
}

async function safeReadJson(response: Response): Promise<unknown> {
  const text = await response.text();
  if (!text.trim()) {
    return {};
  }

  try {
    return JSON.parse(text);
  } catch {
    return { error: text.slice(0, 1000) };
  }
}

function stringifyError(err: unknown): string {
  if (err instanceof Error) {
    return err.message;
  }

  if (typeof err === 'string') {
    return err;
  }

  try {
    return JSON.stringify(err);
  } catch {
    return String(err);
  }
}

function formatCheckedAt(): string {
  return new Date().toLocaleString('zh-CN', { hour12: false });
}

function formatDate(value: string): string {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? value : date.toLocaleString('zh-CN', { hour12: false });
}

function normalizeAlertConfigClient(config: AlertConfig, availableFields?: AlertPayloadField[]): AlertConfig {
  const fields = normalizeAlertFields(availableFields).reduce<Record<string, boolean>>((acc, field) => {
    acc[field.id] = config.fields?.[field.id] ?? field.defaultEnabled;
    return acc;
  }, {});

  return {
    version: 1,
    enabled: Boolean(config.enabled),
    minSeverity: normalizeAlertSeverity(config.minSeverity),
    triggerLogLimit: clampNumber(config.triggerLogLimit, 30, 1, 200),
    fields,
    targets: (config.targets ?? []).map(normalizeAlertTargetClient),
    bindings: (config.bindings ?? []).map(normalizeAlertBindingClient),
  };
}

function normalizeAlertTargetClient(target: AlertTarget, index: number): AlertTarget {
  const id = String(target.id || target.name || `target-${index + 1}`).trim() || `target-${index + 1}`;
  return {
    id,
    name: String(target.name || id).trim() || id,
    enabled: target.enabled !== false,
    url: String(target.url || '').trim(),
    method: normalizeAlertMethod(target.method),
    headers: normalizeHeaderMap(target.headers),
    timeoutMs: clampNumber(target.timeoutMs, 10000, 1000, 120000),
  };
}

function normalizeAlertBindingClient(binding: AlertBinding, index: number): AlertBinding {
  const id = String(binding.id || `binding-${index + 1}`).trim() || `binding-${index + 1}`;
  return {
    id,
    name: String(binding.name || id).trim() || id,
    enabled: binding.enabled !== false,
    sourceJob: String(binding.sourceJob || '').trim(),
    logDomain: String(binding.logDomain || '').trim(),
    logType: String(binding.logType || '').trim(),
    ruleIds: normalizeStringList(binding.ruleIds),
    targetIds: normalizeStringList(binding.targetIds),
  };
}

function normalizeAlertFields(fields?: AlertPayloadField[]): AlertPayloadField[] {
  const fallback: AlertPayloadField[] = [
    { id: 'source', label: 'source', defaultEnabled: true },
    { id: 'severity', label: 'severity', defaultEnabled: true },
    { id: 'log_category', label: 'log_category', defaultEnabled: true },
    { id: 'log_domain', label: 'log_domain', defaultEnabled: true },
    { id: 'log_type', label: 'log_type', defaultEnabled: true },
    { id: 'title', label: 'title', defaultEnabled: true },
    { id: 'analysis', label: 'analysis', defaultEnabled: true },
    { id: 'trigger_total', label: 'trigger_total', defaultEnabled: true },
    { id: 'trigger_logs', label: 'trigger_logs', defaultEnabled: true },
    { id: 'generated_at', label: 'generated_at', defaultEnabled: true },
    { id: 'rule_id', label: 'rule_id', defaultEnabled: false },
    { id: 'rule_name', label: 'rule_name', defaultEnabled: false },
    { id: 'analysis_scenario_id', label: 'analysis_scenario_id', defaultEnabled: false },
    { id: 'analysis_scenario_name', label: 'analysis_scenario_name', defaultEnabled: false },
    { id: 'insight_mode', label: 'insight_mode', defaultEnabled: false },
    { id: 'source_job', label: 'source_job', defaultEnabled: false },
    { id: 'model', label: 'model', defaultEnabled: false },
    { id: 'trigger_query', label: 'trigger_query', defaultEnabled: false },
    { id: 'context_query', label: 'context_query', defaultEnabled: false },
  ];

  return fields?.length ? fields : fallback;
}

function normalizeAlertSeverity(value: unknown): AlertConfig['minSeverity'] {
  return value === 'P0' || value === 'P1' || value === 'P2' || value === 'P3' || value === 'P4' ? value : 'P2';
}

function normalizeAlertMethod(value: unknown): AlertTarget['method'] {
  return value === 'PUT' || value === 'PATCH' ? value : 'POST';
}

function normalizeHeaderMap(headers: unknown): Record<string, string> {
  if (!headers || typeof headers !== 'object' || Array.isArray(headers)) {
    return {};
  }

  return Object.fromEntries(
    Object.entries(headers)
      .map(([key, value]) => [String(key || '').trim(), String(value ?? '').trim()])
      .filter(([key]) => key)
  );
}

function normalizeStringList(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value.map((item) => String(item || '').trim()).filter(Boolean);
  }
  if (typeof value === 'string') {
    return value
      .split(/[,\n]/)
      .map((item) => item.trim())
      .filter(Boolean);
  }
  return [];
}

function clampNumber(value: unknown, fallback: number, min: number, max: number): number {
  const number = Number(value);
  if (!Number.isFinite(number)) {
    return fallback;
  }
  return Math.min(max, Math.max(min, Math.trunc(number)));
}
