export function getAnalysisScenario(id: string | undefined): AnalysisScenario {
  return builtInAnalysisScenarios.find((scenario) => scenario.id === id) ?? builtInAnalysisScenarios[0];
}

export function normalizeCustomScenarios(scenarios: AnalysisScenario[] | undefined): AnalysisScenario[] {
  return (scenarios ?? [])
    .filter((scenario) => scenario.id && scenario.name && scenario.prompt)
    .map((scenario) => ({
      ...scenario,
      builtIn: false,
    }));
}

export function mergeAnalysisScenarios(customScenarios: AnalysisScenario[] | undefined): AnalysisScenario[] {
  const builtInIds = new Set(builtInAnalysisScenarios.map((scenario) => scenario.id));
  const normalizedCustomScenarios = normalizeCustomScenarios(customScenarios).filter(
    (scenario) => !builtInIds.has(scenario.id)
  );

  return [...builtInAnalysisScenarios, ...normalizedCustomScenarios];
}

export function getScenarioFromList(scenarios: AnalysisScenario[], id: string | undefined): AnalysisScenario {
  return scenarios.find((scenario) => scenario.id === id) ?? scenarios[0] ?? builtInAnalysisScenarios[0];
}
