function canUseManualAnalyzer(): boolean {
  const user = grafanaConfig.bootData?.user;
  return user?.isGrafanaAdmin === true || user?.orgRole === 'Admin';
}

function StructuredAnalysisResult({ result }: { result: ParsedAnalysisResult }) {
  if (!result.raw.trim()) {
    return <pre style={preStyle}>尚未调用 LLM。</pre>;
  }

  return (
    <div style={{ display: 'grid', gap: 12 }}>
      <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
        <span style={{ ...severityBadgeStyle, ...getSeverityStyle(result.severity) }}>
          故障等级：{result.severity || '未识别'}
        </span>
        <span style={mutedTextStyle}>以下内容由 LLM 根据当前日志生成，请结合证据复核。</span>
      </div>

      <div style={analysisSectionGridStyle}>
        {result.sections.map((section) => (
          <div key={section.title} style={analysisSectionStyle}>
            <h4 style={{ marginTop: 0 }}>{section.title}</h4>
            <pre style={{ ...preStyle, maxHeight: 260 }}>{section.content}</pre>
          </div>
        ))}
      </div>

      <details>
        <summary style={advancedSummaryStyle}>查看原始 LLM 输出</summary>
        <pre style={preStyle}>{result.raw}</pre>
      </details>
    </div>
  );
}

