async function discoverLogGroups(datasourceUid: string): Promise<LogGroup[]> {
  if (!datasourceUid) {
    return [];
  }

  const entries = await fetchLokiLogEntries({
    datasourceUid,
    query: centralFileLogQuery,
    minutes: 1440,
    limit: 1000,
  });
  const groups = uniqueLogGroups(
    entries.map((entry) => ({
      sourceJob: entry.labels.job || 'central-file-log',
      logDomain: entry.labels.log_domain || '',
      logType: entry.labels.log_type || '',
    }))
  );

  if (groups.length > 0) {
    return groups;
  }

  const [domains, types] = await Promise.all([
    listLokiLabelValues(datasourceUid, 'log_domain'),
    listLokiLabelValues(datasourceUid, 'log_type'),
  ]);

  return uniqueLogGroups(
    domains.flatMap((domain) =>
      (types.length > 0 ? types : ['']).map((type) => ({
        sourceJob: 'central-file-log',
        logDomain: domain,
        logType: type,
      }))
    )
  );
}

function buildDomainSummaries(groups: LogGroup[], rules: AutoAnalysisRule[]): DomainSummary[] {
  const byDomain = new Map<string, LogGroup[]>();

  for (const group of groups) {
    const domain = group.logDomain || '未分类';
    byDomain.set(domain, [...(byDomain.get(domain) ?? []), group]);
  }

  return Array.from(byDomain.entries())
    .map(([domain, domainGroups]) => ({
      domain,
      groups: domainGroups.sort((left, right) => formatLogGroup(left).localeCompare(formatLogGroup(right))),
      configuredCount: domainGroups.filter((group) => findConfiguredRuleForLogGroup(rules, group)).length,
    }))
    .sort((left, right) => left.domain.localeCompare(right.domain));
}

function uniqueLogGroups(groups: LogGroup[]): LogGroup[] {
  const byKey = new Map<string, LogGroup>();
  for (const group of groups) {
    const normalized = {
      sourceJob: (group.sourceJob || 'central-file-log').trim() || 'central-file-log',
      logDomain: (group.logDomain || '').trim(),
      logType: (group.logType || '').trim(),
    };
    if (normalized.logDomain) {
      byKey.set(logGroupKey(normalized), normalized);
    }
  }

  return Array.from(byKey.values()).sort((left, right) => formatLogGroup(left).localeCompare(formatLogGroup(right)));
}

function normalizeConfiguredAutoRules(rules: AutoAnalysisRule[] | undefined): AutoAnalysisRule[] {
  return (rules ?? []).filter((rule) => rule.autoGenerated !== true && Boolean(rule.id || rule.name));
}

function findConfiguredRuleForLogGroup(rules: AutoAnalysisRule[], group: LogGroup): AutoAnalysisRule | undefined {
  return rules.find((rule) => ruleCoversLogGroup(rule, group));
}

function ruleCoversLogGroup(rule: AutoAnalysisRule, group: LogGroup): boolean {
  const ruleJob = (rule.sourceJob || 'central-file-log').trim();
  const groupJob = (group.sourceJob || 'central-file-log').trim();
  const ruleDomain = (rule.logDomain || '').trim();
  const ruleType = (rule.logType || '').trim();

  return ruleJob === groupJob && (!ruleDomain || ruleDomain === group.logDomain) && (!ruleType || ruleType === group.logType);
}

function buildManualLogQL(group: LogGroup, rule: AutoAnalysisRule | undefined): string {
  if (rule?.customLogQL?.trim()) {
    return rule.customLogQL.trim();
  }

  const parts = [`job="${escapeLabelValue(group.sourceJob || 'central-file-log')}"`];
  if (group.logDomain) {
    parts.push(`log_domain="${escapeLabelValue(group.logDomain)}"`);
  }
  if (group.logType) {
    parts.push(`log_type="${escapeLabelValue(group.logType)}"`);
  }

  const triggerPattern = buildKeywordPattern(rule?.triggerKeywords);
  const excludePattern = buildKeywordPattern(rule?.excludeKeywords);

  return [
    `{${parts.join(', ')}}`,
    triggerPattern ? `|~ "(?i)(${triggerPattern})"` : '',
    excludePattern ? `!~ "(?i)(${excludePattern})"` : '',
  ]
    .filter(Boolean)
    .join(' ');
}

function buildManualAnalysisPrompt(basePrompt: string, rule: AutoAnalysisRule | undefined, group: LogGroup | undefined): string {
  const lines = [
    basePrompt,
    '',
    '## 手动分析规则',
    group ? `- 日志组：${formatLogGroup(group)}` : '- 日志组：未选择',
    rule?.name ? `- 规则名称：${rule.name}` : '- 规则名称：默认目录查询',
    rule?.triggerKeywords?.trim() ? `- 触发关键词：${rule.triggerKeywords.trim()}` : '- 触发关键词：未限制',
    rule?.excludeKeywords?.trim() ? `- 排除关键词：${rule.excludeKeywords.trim()}` : '- 排除关键词：未配置',
  ];

  if (rule?.prompt?.trim()) {
    lines.push('', '## 规则补充 Prompt', rule.prompt.trim());
  }

  return lines.join('\n');
}

function buildKeywordPattern(value: string | undefined): string {
  return splitKeywords(value).map(escapeRegex).join('|');
}

function splitKeywords(value: string | undefined): string[] {
  return (value ?? '')
    .split(/[\n,，]+/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function escapeRegex(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function escapeLabelValue(value: string): string {
  return value.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

function logGroupKey(group: LogGroup): string {
  return `${group.sourceJob || 'central-file-log'}::${group.logDomain || '*'}::${group.logType || '*'}`;
}

function formatLogGroup(group: LogGroup): string {
  return `${group.logDomain || '*'}/${group.logType || '*'}`;
}

