function getStatusStyle(status: LLMGatewayStatus['status']) {
  if (status === 'available') {
    return {
      border: 'rgba(115, 191, 105, 0.8)',
      background: 'rgba(115, 191, 105, 0.16)',
      color: 'rgb(115, 191, 105)',
    };
  }

  if (status === 'checking') {
    return {
      border: 'rgba(110, 159, 255, 0.7)',
      background: 'rgba(110, 159, 255, 0.14)',
      color: 'rgb(110, 159, 255)',
    };
  }

  if (status === 'not-configured') {
    return {
      border: 'rgba(250, 222, 42, 0.75)',
      background: 'rgba(250, 222, 42, 0.14)',
      color: 'rgb(250, 222, 42)',
    };
  }

  return {
    border: 'rgba(242, 73, 92, 0.75)',
    background: 'rgba(242, 73, 92, 0.14)',
    color: 'rgb(242, 73, 92)',
  };
}

function getSeverityStyle(severity: string | undefined): React.CSSProperties {
  if (severity === 'P0' || severity === 'P1') {
    return {
      background: 'rgba(242, 73, 92, 0.16)',
      color: 'rgb(242, 73, 92)',
    };
  }

  if (severity === 'P2') {
    return {
      background: 'rgba(255, 152, 48, 0.16)',
      color: 'rgb(255, 152, 48)',
    };
  }

  if (severity === 'P3') {
    return {
      background: 'rgba(250, 222, 42, 0.16)',
      color: 'rgb(250, 222, 42)',
    };
  }

  return {
    background: 'rgba(110, 159, 255, 0.14)',
    color: 'rgb(110, 159, 255)',
  };
}
