export interface ParsedAnalysisSection {
  title: string;
  content: string;
}

export interface ParsedAnalysisResult {
  severity?: string;
  sections: ParsedAnalysisSection[];
  raw: string;
}

const expectedTitles = [
  '故障等级',
  '问题概述',
  '影响判断',
  '关键证据',
  '可能根因',
  '排查步骤',
  '临时处置',
  '长期优化',
];

export function parseAnalysisResult(raw: string): ParsedAnalysisResult {
  const text = raw.trim();
  if (!text) {
    return { sections: [], raw };
  }

  const sections = splitMarkdownSections(text);
  const severitySection = sections.find((section) => section.title === '故障等级');

  return {
    severity: severitySection ? extractSeverity(severitySection.content) : undefined,
    sections,
    raw,
  };
}

function splitMarkdownSections(text: string): ParsedAnalysisSection[] {
  const matches = Array.from(text.matchAll(/^##\s+(.+?)\s*$/gm));
  if (!matches.length) {
    return [{ title: '原始分析', content: text }];
  }

  const sections: ParsedAnalysisSection[] = [];

  for (let index = 0; index < matches.length; index += 1) {
    const match = matches[index];
    const title = normalizeTitle(match[1]);
    const start = (match.index ?? 0) + match[0].length;
    const end = matches[index + 1]?.index ?? text.length;
    const content = text.slice(start, end).trim();

    if (title && content) {
      sections.push({ title, content });
    }
  }

  const orderedSections = expectedTitles
    .map((title) => sections.find((section) => section.title === title))
    .filter(Boolean) as ParsedAnalysisSection[];
  const extraSections = sections.filter((section) => !expectedTitles.includes(section.title));

  return [...orderedSections, ...extraSections];
}

function normalizeTitle(title: string): string {
  const cleaned = title.replace(/[：:]\s*$/, '').trim();
  return expectedTitles.find((expected) => cleaned.includes(expected)) ?? cleaned;
}

function extractSeverity(content: string): string | undefined {
  const normalized = content.toUpperCase();
  const match = normalized.match(/\b(P0|P1|P2|P3)\b/);
  if (match) {
    return match[1];
  }

  if (/观察|觀察/.test(content)) {
    return '观察';
  }

  return undefined;
}
