function WorkerRuntimePanel(props: {
  rules: AutoAnalysisRule[];
  runtime: Record<string, WorkerRuleRuntimeState>;
  rulesPath?: string;
  cachePath?: string;
  selectedGroup?: LogGroup;
  loading: boolean;
  error?: string;
  onRefresh: () => void;
}) {
  const scopedRules = props.selectedGroup
    ? props.rules.filter((rule) => ruleCoversLogGroup(rule, props.selectedGroup as LogGroup))
    : props.rules;
  const allBatchCount = scopedRules.filter(
    (rule) => normalizeTriggerSelectionMode(rule.triggerSelectionMode) === 'all_batches'
  ).length;
  const checkpointCount = scopedRules.filter((rule) => props.runtime[rule.id]?.hasCheckpoint).length;
  const scopeLabel = props.selectedGroup ? `${formatLogGroup(props.selectedGroup)} 的规则` : '已保存规则';

  return (
    <section style={runtimePanelStyle}>
      <div style={sectionHeaderStyle}>
        <div>
          <div style={panelEyebrowStyle}>Worker Runtime</div>
          <h3 style={{ margin: 0 }}>处理进度 / 续传位点</h3>
          <p style={mutedTextStyle}>
            页面可见时每 60 秒刷新状态；Loki 最新命中探测由 Worker 缓存 5 分钟，避免重复查询。
          </p>
        </div>
        <Button variant="secondary" disabled={props.loading} onClick={props.onRefresh}>
          {props.loading ? '刷新中...' : '刷新进度'}
        </Button>
      </div>

      <div style={runtimeSummaryGridStyle}>
        <div style={runtimeSummaryItemStyle}>
          <span style={smallMetaStyle}>已保存规则</span>
          <strong>{scopedRules.length}</strong>
        </div>
        <div style={runtimeSummaryItemStyle}>
          <span style={smallMetaStyle}>全量分批</span>
          <strong>{allBatchCount}</strong>
        </div>
        <div style={runtimeSummaryItemStyle}>
          <span style={smallMetaStyle}>已建立断点</span>
          <strong>{checkpointCount}</strong>
        </div>
        <div style={runtimePathItemStyle}>
          <span style={smallMetaStyle}>规则文件</span>
          <code style={runtimeCodeStyle}>{props.rulesPath || 'Worker 未返回'}</code>
          <span style={smallMetaStyle}>断点缓存</span>
          <code style={runtimeCodeStyle}>{props.cachePath || 'Worker 未返回'}</code>
        </div>
      </div>

      {props.error && (
        <Alert title="处理进度读取失败" severity="warning">
          {props.error}
        </Alert>
      )}

      <div style={runtimeRulesHeaderStyle}>
        <strong>{scopeLabel}</strong>
        <span style={smallMetaStyle}>展示 {scopedRules.length} 条</span>
      </div>
      <div style={runtimeRuleGridStyle}>
        {scopedRules.length === 0 && (
          <div style={emptyRuntimeStyle}>当前日志目录还没有保存的采集规则；保存规则后会在这里显示续传状态。</div>
        )}
        {scopedRules.map((rule) => {
          const state = props.runtime[rule.id];
          const mode = normalizeTriggerSelectionMode(state?.triggerSelectionMode ?? rule.triggerSelectionMode);
          const hasCheckpoint = Boolean(state?.hasCheckpoint);
          const progressStatus = describeRuntimeProgress(state, hasCheckpoint, state?.enabled ?? rule.enabled);

          return (
            <article key={rule.id} style={runtimeRuleStyle}>
              <div style={runtimeRuleTopStyle}>
                <strong>{rule.name || rule.id}</strong>
                <span style={runtimeModePillStyle}>{formatTriggerSelectionModeLabel(mode)}</span>
              </div>
              <div style={runtimeRuleMetaStyle}>
                <span>规则 ID：<code style={runtimeCodeStyle}>{rule.id}</code></span>
                <span>状态：{(state?.enabled ?? rule.enabled) ? '已启用' : '已停用'}</span>
              </div>
              {mode === 'all_batches' ? (
                <>
                  <div style={runtimeProgressGridStyle}>
                    <div style={runtimeProgressItemStyle}>
                      <span style={smallMetaStyle}>当前命中日志最新时间（Loki）</span>
                      <strong>
                        {state?.latestProbeError
                          ? '探测失败'
                          : state?.latestMatchedTimestamp
                            ? formatRuntimeTimestamp(state.latestMatchedTimestamp)
                            : state?.latestProbeAt
                              ? '当前探测窗口无命中'
                              : '等待探测'}
                      </strong>
                    </div>
                    <div style={runtimeProgressItemStyle}>
                      <span style={smallMetaStyle}>当前已处理到</span>
                      <strong>{hasCheckpoint ? formatRuntimeTimestamp(state?.lastProcessedTimestamp) : '尚未建立断点'}</strong>
                    </div>
                    <div style={runtimeProgressItemStyle}>
                      <span style={smallMetaStyle}>处理滞后</span>
                      <strong>{formatRuntimeLag(state?.lagSeconds, hasCheckpoint, Boolean(state?.latestProbeAt))}</strong>
                    </div>
                    <div style={runtimeProgressItemStyle}>
                      <span style={smallMetaStyle}>状态</span>
                      <strong style={{ color: progressStatus.color }}>{progressStatus.label}</strong>
                    </div>
                  </div>
                  <div style={runtimeProbeMetaStyle}>
                    <span>断点更新于：{hasCheckpoint ? formatRuntimeTimestamp(state?.updatedAt) : '—'}</span>
                    <span>数据更新于：{formatRuntimeTimestamp(state?.latestProbeAt)}</span>
                    <span>运行状态：{formatRuntimeRunStatus(state)}</span>
                    <span>最近耗时：{formatRuntimeRunDuration(state)}</span>
                    <span>开始于：{formatRuntimeTimestamp(state?.latestRunStartedAt)}</span>
                    <span>结束于：{formatRuntimeTimestamp(state?.latestRunFinishedAt)}</span>
                    <span>运行结果：{state?.latestRunMessage || '—'}</span>
                  </div>
                  {state?.latestProbeError && <p style={runtimeProbeErrorStyle}>{state.latestProbeError}</p>}
                  {state?.latestRunError && <p style={runtimeProbeErrorStyle}>{state.latestRunError}</p>}
                  <p style={runtimeHintStyle}>
                    {hasCheckpoint
                      ? '下一轮会从该断点向前回看少量重叠日志后继续发送；重叠部分会按已处理缓存去重。'
                      : `首次运行会从最近 ${rule.lookbackMinutes ?? 5} 分钟开始；首批处理成功后自动建立断点。`}
                  </p>
                </>
              ) : (
                <>
                  <div style={runtimeProbeMetaStyle}>
                    <span>运行状态：{formatRuntimeRunStatus(state)}</span>
                    <span>最近耗时：{formatRuntimeRunDuration(state)}</span>
                    <span>开始于：{formatRuntimeTimestamp(state?.latestRunStartedAt)}</span>
                    <span>结束于：{formatRuntimeTimestamp(state?.latestRunFinishedAt)}</span>
                    <span>运行结果：{state?.latestRunMessage || '—'}</span>
                  </div>
                  {state?.latestRunError && <p style={runtimeProbeErrorStyle}>{state.latestRunError}</p>}
                  <p style={runtimeHintStyle}>
                    {formatTriggerSelectionModeLabel(mode)}不维护续传断点；每轮按查询窗口重新采样，已处理日志仍会用缓存避免重复发送。
                  </p>
                </>
              )}
            </article>
          );
        })}
      </div>
    </section>
  );
}

function formatTriggerSelectionModeLabel(mode: AutoAnalysisRule['triggerSelectionMode']): string {
  if (mode === 'all_batches') {
    return '全量分批';
  }
  if (mode === 'latest') {
    return '按时间最新';
  }
  return '智能采样';
}

function formatRuntimeTimestamp(value: string | undefined): string {
  if (!value) {
    return '—';
  }

  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return value;
  }
  return date.toLocaleString('zh-CN', { hour12: false });
}

function formatRuntimeLag(lagSeconds: number | undefined, hasCheckpoint: boolean, hasProbe: boolean): string {
  if (!hasCheckpoint) {
    return '尚未建立断点';
  }
  if (!hasProbe || !Number.isFinite(lagSeconds)) {
    return '—';
  }

  const seconds = Math.max(0, Math.floor(lagSeconds ?? 0));
  if (seconds < 60) {
    return `${seconds} 秒`;
  }
  if (seconds < 3600) {
    return `${Math.floor(seconds / 60)} 分 ${seconds % 60} 秒`;
  }
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  return `${hours} 小时 ${minutes} 分`;
}

function formatRuntimeRunDuration(state: WorkerRuleRuntimeState | undefined): string {
  const durationMs =
    state?.latestRunStatus === 'running' && state.latestRunStartedAt
      ? Date.now() - new Date(state.latestRunStartedAt).getTime()
      : state?.latestRunDurationMs;
  if (!Number.isFinite(durationMs)) {
    return '—';
  }

  const seconds = Math.max(0, Math.floor((durationMs ?? 0) / 1000));
  if (seconds < 60) {
    return `${seconds} 秒`;
  }
  if (seconds < 3600) {
    return `${Math.floor(seconds / 60)} 分 ${seconds % 60} 秒`;
  }
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  return `${hours} 小时 ${minutes} 分`;
}

function formatRuntimeRunStatus(state: WorkerRuleRuntimeState | undefined): string {
  switch (state?.latestRunStatus) {
    case 'running':
      return '运行中';
    case 'success':
      return '已完成';
    case 'empty':
      return '无新增';
    case 'timeout':
      return '超时';
    case 'error':
    case 'failed':
      return '失败';
    case 'skipped':
      return '已跳过';
    default:
      return '尚未运行';
  }
}

function describeRuntimeProgress(
  state: WorkerRuleRuntimeState | undefined,
  hasCheckpoint: boolean,
  enabled: boolean
): { label: string; color: string } {
  if (!enabled) {
    return { label: '已停用', color: 'var(--text-secondary)' };
  }
  if (state?.latestRunStatus === 'running') {
    return { label: '运行中', color: '#93c5fd' };
  }
  if (state?.latestRunStatus === 'timeout') {
    return { label: '规则超时', color: '#fca5a5' };
  }
  if (state?.latestRunStatus === 'error' || state?.latestRunStatus === 'failed') {
    return { label: '规则失败', color: '#fca5a5' };
  }
  if (state?.latestProbeError) {
    return { label: '探测失败', color: '#fca5a5' };
  }
  if (!hasCheckpoint) {
    return { label: '尚未建立断点', color: '#fbbf24' };
  }
  if (!state?.latestProbeAt) {
    return { label: '等待探测', color: 'var(--text-secondary)' };
  }
  if (!state.latestMatchedTimestamp) {
    return { label: '当前探测窗口无命中', color: '#93c5fd' };
  }
  if ((state.lagSeconds ?? 0) <= 0) {
    return { label: '已追平', color: '#5eead4' };
  }
  return { label: '存在积压', color: '#fbbf24' };
}

function canManageConfig(): boolean {
  const user = grafanaConfig.bootData?.user;
  return user?.isGrafanaAdmin === true || user?.orgRole === 'Admin';
}

function normalizeDraftScenario(scenario: AnalysisScenario): AnalysisScenario {
  return {
    id: normalizeScenarioId(scenario.id || createScenarioId()),
    name: scenario.name.trim(),
    description: scenario.description.trim(),
    prompt: scenario.prompt.trim(),
    builtIn: false,
  };
}

function hasUnsavedScenarioChanges(
  draftScenario: AnalysisScenario,
  editingScenarioId: string,
  scenarios: AnalysisScenario[]
): boolean {
  if (draftScenario.builtIn) {
    return false;
  }

  const normalizedDraft = normalizeDraftScenario(draftScenario);
  const savedScenario = scenarios.find((scenario) => scenario.id === editingScenarioId);
  if (!savedScenario) {
    return Boolean(normalizedDraft.id || normalizedDraft.name || normalizedDraft.description || normalizedDraft.prompt);
  }

  return (
    normalizedDraft.id !== savedScenario.id ||
    normalizedDraft.name !== savedScenario.name ||
    normalizedDraft.description !== savedScenario.description ||
    normalizedDraft.prompt !== savedScenario.prompt
  );
}

function normalizeDraftRule(rule: AutoAnalysisRule): AutoAnalysisRule {
  const sourceJob = (rule.sourceJob ?? 'central-file-log').trim() || 'central-file-log';
  const logDomain = (rule.logDomain ?? '').trim();
  const logType = (rule.logType ?? '').trim();

  return {
    id: normalizeScenarioId(rule.id || createScenarioId('auto-rule')),
    name: (rule.name ?? '').trim(),
    enabled: rule.enabled !== false,
    sourceJob,
    logDomain,
    logType,
    analysisScenarioId: (rule.analysisScenarioId ?? 'general').trim() || 'general',
    scenarioName: (rule.scenarioName ?? '').trim(),
    scenarioDescription: (rule.scenarioDescription ?? '').trim(),
    scenarioPrompt: (rule.scenarioPrompt ?? '').trim(),
    triggerKeywords: (rule.triggerKeywords ?? '').trim(),
    excludeKeywords: (rule.excludeKeywords ?? '').trim(),
    triggerSelectionMode: normalizeTriggerSelectionMode(rule.triggerSelectionMode),
    triggerBatchSize: normalizeNumber(rule.triggerBatchSize, 10),
    insightMode: normalizeInsightMode(rule.insightMode),
    sensitiveOperationMode: normalizeSensitiveOperationMode(rule.sensitiveOperationMode),
    sensitiveOperationRule: (rule.sensitiveOperationRule ?? '').trim(),
    customLogQL: normalizeCustomLogQL(rule, sourceJob, logDomain, logType),
    contextLogQL: normalizeContextLogQL(rule, sourceJob, logDomain, logType),
    includeContextLogs: rule.includeContextLogs !== false,
    prompt: (rule.prompt ?? '').trim(),
    lookbackMinutes: normalizeNumber(rule.lookbackMinutes, 5),
    contextLookbackMinutes: normalizeNumber(rule.contextLookbackMinutes, 30),
    triggerLimit: normalizeNumber(rule.triggerLimit, 100),
    contextLimit: normalizeNumber(rule.contextLimit, 300),
    maxTriggerEvents: normalizeNumber(rule.maxTriggerEvents, 10),
    maxContextLines: normalizeNumber(rule.maxContextLines, 80),
    promptTriggerSampleMax: normalizeNumber(rule.promptTriggerSampleMax, 10),
    promptContextSampleMax: normalizeNumber(rule.promptContextSampleMax, 80),
    contextAroundTriggerMinutes: normalizeNumber(rule.contextAroundTriggerMinutes, 5),
    autoGenerated: rule.autoGenerated === true,
  };
}

function normalizeCustomLogQL(
  rule: AutoAnalysisRule,
  sourceJob: string,
  logDomain: string,
  logType: string
): string {
  const explicit = (rule.customLogQL ?? '').trim();
  if (explicit) {
    return explicit;
  }

  const triggerQuery = (rule.triggerQuery ?? '').trim();
  if (!triggerQuery) {
    return '';
  }

  const generatedTriggerQuery = buildDefaultTriggerLogQL(rule, sourceJob, logDomain, logType);
  return sameLogQL(triggerQuery, generatedTriggerQuery) ? '' : triggerQuery;
}

function normalizeContextLogQL(
  rule: AutoAnalysisRule,
  sourceJob: string,
  logDomain: string,
  logType: string
): string {
  const explicit = (rule.contextLogQL ?? '').trim();
  if (explicit) {
    return explicit;
  }

  const contextQuery = (rule.contextQuery ?? '').trim();
  if (!contextQuery) {
    return '';
  }

  const generatedContextQuery = buildDefaultContextLogQL(sourceJob, logDomain, logType);
  return sameLogQL(contextQuery, generatedContextQuery) ? '' : contextQuery;
}

function buildDefaultTriggerLogQL(
  rule: AutoAnalysisRule,
  sourceJob: string,
  logDomain: string,
  logType: string
): string {
  const selector = buildDefaultContextLogQL(sourceJob, logDomain, logType);
  const keywordRegex = keywordsToRegex(rule.triggerKeywords);
  const excludeRegex = keywordsToRegex(rule.excludeKeywords);
  const triggerQuery = keywordRegex ? `${selector} |~ "${keywordRegex}"` : selector;
  return excludeRegex ? `${triggerQuery} !~ "${excludeRegex}"` : triggerQuery;
}

function buildDefaultContextLogQL(sourceJob: string, logDomain: string, logType: string): string {
  const selectors = [`job="${escapeLogQLLabelValue(sourceJob || 'central-file-log')}"`];
  selectors.push(logDomain ? `log_domain="${escapeLogQLLabelValue(logDomain)}"` : 'log_domain=~".+"');
  selectors.push(logType ? `log_type="${escapeLogQLLabelValue(logType)}"` : 'log_type=~".+"');
  return `{${selectors.join(', ')}}`;
}

function keywordsToRegex(value: string | undefined): string {
  const keywords = String(value ?? '')
    .split(/[\n,，;；]+/)
    .map((item) => item.trim())
    .filter(Boolean);

  return keywords.length > 0 ? `(?i)(${keywords.map(escapeRegex).join('|')})` : '';
}

function escapeLogQLLabelValue(value: string): string {
  return value.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

function escapeRegex(value: string): string {
  return value.replace(/[\\^$.*+?()[\]{}|]/g, '\\$&');
}

function sameLogQL(left: string, right: string): boolean {
  return left.replace(/\s+/g, ' ').trim() === right.replace(/\s+/g, ' ').trim();
}

function normalizeTriggerSelectionMode(value: AutoAnalysisRule['triggerSelectionMode']): AutoAnalysisRule['triggerSelectionMode'] {
  return value === 'latest' || value === 'all_batches' ? value : 'smart';
}

function normalizeInsightMode(value: AutoAnalysisRule['insightMode']): AutoAnalysisRule['insightMode'] {
  return value === 'audit' ? 'audit' : 'incident';
}

function normalizeSensitiveOperationMode(value: AutoAnalysisRule['sensitiveOperationMode']): AutoAnalysisRule['sensitiveOperationMode'] {
  return value === 'custom' || value === 'sensitive' || value === 'normal' ? value : 'ai';
}

function normalizeOptionalInsightMode(value: AutoAnalysisRule['insightMode']): AutoAnalysisRule['insightMode'] | undefined {
  return value === 'audit' || value === 'incident' ? value : undefined;
}

function normalizeOptionalSensitiveOperationMode(
  value: AutoAnalysisRule['sensitiveOperationMode']
): AutoAnalysisRule['sensitiveOperationMode'] | undefined {
  return value === 'ai' || value === 'custom' || value === 'sensitive' || value === 'normal' ? value : undefined;
}

function needsSensitiveOperationRule(
  insightMode: AutoAnalysisRule['insightMode'],
  sensitiveOperationMode: AutoAnalysisRule['sensitiveOperationMode']
): boolean {
  return normalizeInsightMode(insightMode) === 'audit' && normalizeSensitiveOperationMode(sensitiveOperationMode) === 'custom';
}

function normalizeAutoRules(rules: AutoAnalysisRule[] | undefined): AutoAnalysisRule[] {
  return (rules ?? [])
    .map((rule) => normalizeDraftRule(rule))
    .filter((rule) => rule.id && rule.name);
}

function normalizeConfiguredAutoRules(rules: AutoAnalysisRule[] | undefined): AutoAnalysisRule[] {
  return normalizeAutoRules(rules).filter((rule) => rule.autoGenerated !== true);
}

function normalizeLogGroupScenarioBindings(bindings: LogGroupScenarioBinding[] | undefined): LogGroupScenarioBinding[] {
  const byKey = new Map<string, LogGroupScenarioBinding>();
  for (const binding of bindings ?? []) {
    const insightMode = normalizeOptionalInsightMode(binding.insightMode);
    const sensitiveOperationMode = normalizeOptionalSensitiveOperationMode(binding.sensitiveOperationMode);
    const sensitiveOperationRule = (binding.sensitiveOperationRule ?? '').trim();
    const normalized: LogGroupScenarioBinding = {
      sourceJob: (binding.sourceJob || 'central-file-log').trim() || 'central-file-log',
      logDomain: (binding.logDomain || '').trim(),
      logType: (binding.logType || '').trim(),
      analysisScenarioId: (binding.analysisScenarioId || '').trim(),
      ...(insightMode ? { insightMode } : {}),
      ...(sensitiveOperationMode ? { sensitiveOperationMode } : {}),
      ...(sensitiveOperationRule ? { sensitiveOperationRule } : {}),
    };
    if (!normalized.logDomain || !normalized.analysisScenarioId) {
      continue;
    }
    byKey.set(logGroupKeyFromParts(normalized.sourceJob, normalized.logDomain, normalized.logType), normalized);
  }
  return Array.from(byKey.values()).sort((left, right) =>
    logGroupKeyFromParts(left.sourceJob, left.logDomain, left.logType).localeCompare(
      logGroupKeyFromParts(right.sourceJob, right.logDomain, right.logType)
    )
  );
}

function mergeLogGroupScenarioBindings(
  explicitBindings: LogGroupScenarioBinding[],
  inferredBindings: LogGroupScenarioBinding[]
): LogGroupScenarioBinding[] {
  const byKey = new Map<string, LogGroupScenarioBinding>();
  for (const binding of normalizeLogGroupScenarioBindings(inferredBindings)) {
    byKey.set(logGroupKeyFromParts(binding.sourceJob, binding.logDomain, binding.logType), binding);
  }
  for (const binding of normalizeLogGroupScenarioBindings(explicitBindings)) {
    byKey.set(logGroupKeyFromParts(binding.sourceJob, binding.logDomain, binding.logType), binding);
  }
  return normalizeLogGroupScenarioBindings(Array.from(byKey.values()));
}

function deriveLogGroupScenarioBindingsFromRules(rules: AutoAnalysisRule[]): LogGroupScenarioBinding[] {
  return normalizeLogGroupScenarioBindings(
    normalizeConfiguredAutoRules(rules)
      .filter((rule) => rule.logDomain && rule.analysisScenarioId)
      .map((rule) => ({
        sourceJob: rule.sourceJob || 'central-file-log',
        logDomain: rule.logDomain || '',
        logType: rule.logType || '',
        analysisScenarioId: rule.analysisScenarioId || 'general',
        insightMode: normalizeInsightMode(rule.insightMode),
        sensitiveOperationMode: normalizeSensitiveOperationMode(rule.sensitiveOperationMode),
        sensitiveOperationRule: (rule.sensitiveOperationRule ?? '').trim(),
      }))
  );
}

function findLogGroupScenarioBinding(
  bindings: LogGroupScenarioBinding[],
  group: LogGroup
): LogGroupScenarioBinding | undefined {
  const key = logGroupKey(group);
  return bindings.find((binding) => logGroupKeyFromParts(binding.sourceJob, binding.logDomain, binding.logType) === key);
}

function upsertLogGroupScenarioBinding(
  bindings: LogGroupScenarioBinding[],
  group: LogGroup,
  analysisScenarioId: string,
  insightMode?: AutoAnalysisRule['insightMode'],
  sensitiveOperationMode?: AutoAnalysisRule['sensitiveOperationMode'],
  sensitiveOperationRule?: string
): LogGroupScenarioBinding[] {
  const normalizedInsightMode = normalizeOptionalInsightMode(insightMode);
  const normalizedSensitiveOperationMode = normalizeOptionalSensitiveOperationMode(
    normalizedInsightMode === 'audit' ? sensitiveOperationMode : 'ai'
  );
  const nextBinding: LogGroupScenarioBinding = {
    sourceJob: group.sourceJob,
    logDomain: group.logDomain,
    logType: group.logType,
    analysisScenarioId,
    ...(normalizedInsightMode ? { insightMode: normalizedInsightMode } : {}),
    ...(normalizedSensitiveOperationMode ? { sensitiveOperationMode: normalizedSensitiveOperationMode } : {}),
    ...(normalizedInsightMode === 'audit' && normalizedSensitiveOperationMode === 'custom' && sensitiveOperationRule?.trim()
      ? { sensitiveOperationRule: sensitiveOperationRule.trim() }
      : {}),
  };
  const next = [
    ...bindings.filter((binding) => logGroupKeyFromParts(binding.sourceJob, binding.logDomain, binding.logType) !== logGroupKey(group)),
    nextBinding,
  ];
  return normalizeLogGroupScenarioBindings(next);
}

function getLogGroupResultProfile(
  binding: LogGroupScenarioBinding | undefined,
  groupRules: AutoAnalysisRule[],
  selectedRule?: AutoAnalysisRule
): { insightMode: InsightMode; sensitiveOperationMode: SensitiveOperationMode; sensitiveOperationRule: string } {
  const source =
    binding?.insightMode || binding?.sensitiveOperationMode || binding?.sensitiveOperationRule
      ? binding
      : selectedRule ?? groupRules.find((rule) => rule.insightMode || rule.sensitiveOperationMode || rule.sensitiveOperationRule);
  const insightMode = normalizeInsightMode(source?.insightMode) as InsightMode;
  const sensitiveOperationMode = normalizeSensitiveOperationMode(
    insightMode === 'audit' ? source?.sensitiveOperationMode : 'ai'
  ) as SensitiveOperationMode;
  const sensitiveOperationRule =
    insightMode === 'audit' && sensitiveOperationMode === 'custom' ? (source?.sensitiveOperationRule ?? '').trim() : '';
  return { insightMode, sensitiveOperationMode, sensitiveOperationRule };
}

function hydrateRuleScenario(rule: AutoAnalysisRule, scenarios: AnalysisScenario[]): AutoAnalysisRule {
  const configuredScenario = scenarios.find((scenario) => scenario.id === rule.analysisScenarioId);
  if (configuredScenario) {
    return {
      ...rule,
      analysisScenarioId: configuredScenario.id,
      scenarioName: configuredScenario.name,
      scenarioDescription: configuredScenario.description,
      scenarioPrompt: configuredScenario.prompt,
    };
  }

  const ruleScenarioId = (rule.analysisScenarioId ?? '').trim();
  const ruleScenarioName = (rule.scenarioName ?? '').trim();
  const ruleScenarioPrompt = (rule.scenarioPrompt ?? '').trim();
  if (ruleScenarioId && !isBuiltInScenarioId(ruleScenarioId) && ruleScenarioName && ruleScenarioPrompt) {
    return {
      ...rule,
      analysisScenarioId: ruleScenarioId,
      scenarioName: ruleScenarioName,
      scenarioDescription: (rule.scenarioDescription ?? '').trim(),
      scenarioPrompt: ruleScenarioPrompt,
    };
  }

  const scenario = getScenarioFromList(scenarios, rule.analysisScenarioId);
  return {
    ...rule,
    analysisScenarioId: scenario.id,
    scenarioName: scenario.name,
    scenarioDescription: scenario.description,
    scenarioPrompt: scenario.prompt,
  };
}

function extractCustomScenariosFromRules(rules: AutoAnalysisRule[]): AnalysisScenario[] {
  const byId = new Map<string, AnalysisScenario>();

  for (const rule of rules) {
    const id = (rule.analysisScenarioId ?? '').trim();
    const name = (rule.scenarioName ?? '').trim();
    const description = (rule.scenarioDescription ?? '').trim();
    const prompt = (rule.scenarioPrompt ?? '').trim();
    if (!id || isBuiltInScenarioId(id) || !name || !prompt) {
      continue;
    }
    byId.set(id, { id, name, description, prompt, builtIn: false });
  }

  return Array.from(byId.values());
}

function mergeCustomScenarios(base: AnalysisScenario[], incoming: AnalysisScenario[]): AnalysisScenario[] {
  const byId = new Map<string, AnalysisScenario>();
  for (const scenario of normalizeCustomScenarios(base)) {
    byId.set(scenario.id, scenario);
  }
  for (const scenario of normalizeCustomScenarios(incoming)) {
    byId.set(scenario.id, scenario);
  }
  return Array.from(byId.values());
}

function createDraftRuleForGroup(group: LogGroup, defaultScenarioId: string): AutoAnalysisRule {
  return {
    ...emptyAutoRule(),
    id: normalizeScenarioId(`${group.logDomain}-${group.logType || 'all'}-risk`),
    name: `${formatLogGroup(group)} 自动分析`,
    sourceJob: group.sourceJob,
    logDomain: group.logDomain,
    logType: group.logType,
    analysisScenarioId: defaultScenarioId || 'general',
    prompt: '',
    autoGenerated: false,
  };
}

async function loadRealLogGroups(): Promise<LogGroup[]> {
  const dataSources = await listLokiDataSources();
  const datasource = dataSources[0];
  if (!datasource) {
    return [];
  }
  const centralFileLogSelector = '{job="central-file-log", log_domain=~".+", log_type=~".+"}';

  const recentGroupsPromise = fetchLokiLogEntries({
    datasourceUid: datasource.uid,
    query: centralFileLogSelector,
    minutes: 24 * 60,
    limit: 1000,
  })
    .then((entries) =>
      entries.map((entry) => logGroupFromLabels(entry.labels)).filter(isLogGroup)
    )
    .catch(() => [] as LogGroup[]);

  const seriesGroupsPromise = listLokiSeriesLabelSets({
    datasourceUid: datasource.uid,
    match: centralFileLogSelector,
    minutes: 24 * 60,
  })
    .then((series) =>
      series.map((labels) => logGroupFromLabels(labels)).filter(isLogGroup)
    )
    .catch(() => [] as LogGroup[]);

  const [recentGroups, seriesGroups] = await Promise.all([recentGroupsPromise, seriesGroupsPromise]);
  return uniqueLogGroups([...recentGroups, ...seriesGroups]);
}

function logGroupFromLabels(labels: Record<string, string>): LogGroup | undefined {
  const labelGroup =
    labels.log_domain && labels.log_type
      ? {
          sourceJob: labels.job || 'central-file-log',
          logDomain: labels.log_domain,
          logType: labels.log_type,
        }
      : undefined;
  const fromFilename = parseLogGroupFromFilename(labels.filename || labels.__path__ || labels.path || '');
  if (fromFilename) {
    if (
      labelGroup &&
      (labelGroup.logDomain !== fromFilename.logDomain || labelGroup.logType !== fromFilename.logType)
    ) {
      return labelGroup;
    }

    return {
      sourceJob: labels.job || 'central-file-log',
      ...fromFilename,
    };
  }

  if ((labels.job || 'central-file-log') === 'central-file-log') {
    return labelGroup;
  }

  return labelGroup;
}

function isLogGroup(group: LogGroup | undefined): group is LogGroup {
  return Boolean(group?.logDomain && group.logType);
}

function parseLogGroupFromFilename(filename: string): Pick<LogGroup, 'logDomain' | 'logType'> | undefined {
  const normalized = filename.replace(/\\/g, '/');
  const match = normalized.match(/(?:^|\/)(?:data\/logs|var\/log\/central)\/([^/]+)\/([^/]+)(?:\/|$)/);
  if (!match) {
    return undefined;
  }

  return {
    logDomain: decodeLogPathSegment(match[1]),
    logType: decodeLogPathSegment(match[2]),
  };
}

function decodeLogPathSegment(value: string): string {
  try {
    return decodeURIComponent(value).trim();
  } catch {
    return value.trim();
  }
}

function buildDomainSummaries(groups: LogGroup[], rules: AutoAnalysisRule[]): DomainSummary[] {
  const byDomain = new Map<string, LogGroup[]>();
  for (const group of groups) {
    const domain = group.logDomain || 'unknown';
    byDomain.set(domain, [...(byDomain.get(domain) ?? []), group]);
  }

  return Array.from(byDomain.entries())
    .map(([domain, domainGroups]) => ({
      domain,
      groups: domainGroups.sort((left, right) => (left.logType || '*').localeCompare(right.logType || '*')),
      configuredCount: domainGroups.filter((group) => findConfiguredRulesForLogGroup(rules, group).length > 0).length,
      configuredRuleCount: domainGroups.reduce(
        (total, group) => total + findConfiguredRulesForLogGroup(rules, group).length,
        0
      ),
    }))
    .sort((left, right) => left.domain.localeCompare(right.domain));
}

function uniqueLogGroups(groups: LogGroup[]): LogGroup[] {
  const byKey = new Map<string, LogGroup>();
  for (const group of groups) {
    const normalized = {
      sourceJob: (group.sourceJob || 'central-file-log').trim() || 'central-file-log',
      logDomain: (group.logDomain || '').trim(),
      logType: (group.logType || '').trim(),
    };
    if (!normalized.logDomain) {
      continue;
    }
    byKey.set(logGroupKey(normalized), normalized);
  }

  return Array.from(byKey.values()).sort((left, right) => formatLogGroup(left).localeCompare(formatLogGroup(right)));
}

function findConfiguredRulesForLogGroup(rules: AutoAnalysisRule[], group: LogGroup): AutoAnalysisRule[] {
  return rules
    .filter((rule) => rule.autoGenerated !== true && ruleCoversLogGroup(rule, group))
    .sort((left, right) => {
      const specificityDiff = ruleSpecificity(right, group) - ruleSpecificity(left, group);
      return specificityDiff || left.name.localeCompare(right.name) || left.id.localeCompare(right.id);
    });
}

function upsertConfiguredRule(
  rules: AutoAnalysisRule[],
  nextRule: AutoAnalysisRule,
  previousRuleId: string | undefined
): AutoAnalysisRule[] {
  const existingIndex = rules.findIndex((rule) => rule.id === (previousRuleId || nextRule.id));
  if (existingIndex < 0) {
    return [...rules, nextRule];
  }

  return rules.map((rule, index) => (index === existingIndex ? nextRule : rule));
}

function ruleSpecificity(rule: AutoAnalysisRule, group: LogGroup): number {
  const ruleDomain = (rule.logDomain || '').trim();
  const ruleType = (rule.logType || '').trim();
  let score = 0;
  if (ruleDomain && ruleDomain === group.logDomain) {
    score += 2;
  }
  if (ruleType && ruleType === group.logType) {
    score += 4;
  }
  return score;
}

function ruleCoversLogGroup(rule: AutoAnalysisRule, group: LogGroup): boolean {
  const ruleJob = (rule.sourceJob || 'central-file-log').trim();
  const groupJob = (group.sourceJob || 'central-file-log').trim();
  const ruleDomain = (rule.logDomain || '').trim();
  const ruleType = (rule.logType || '').trim();

  return ruleJob === groupJob && (!ruleDomain || ruleDomain === group.logDomain) && (!ruleType || ruleType === group.logType);
}

function ruleBelongsToExactLogGroup(rule: AutoAnalysisRule, group: LogGroup): boolean {
  return (
    logGroupKeyFromParts(rule.sourceJob, rule.logDomain, rule.logType) ===
    logGroupKeyFromParts(group.sourceJob, group.logDomain, group.logType)
  );
}

function formatLogGroup(group: LogGroup): string {
  return `${group.logDomain || '*'}/${group.logType || '*'}`;
}

function logGroupKey(group: LogGroup): string {
  return logGroupKeyFromParts(group.sourceJob, group.logDomain, group.logType);
}

function logGroupKeyFromParts(sourceJob?: string, logDomain?: string, logType?: string): string {
  const job = (sourceJob || 'central-file-log').trim() || 'central-file-log';
  const domain = (logDomain || '').trim() || '*';
  const type = (logType || '').trim() || '*';
  return `${job}::${domain}::${type}`;
}

