function formatWorkerRulesSaveDetail(result: WorkerRulesSaveResult): string {
  const target = result.rulesPath || 'worker /rules';
  const hostHint =
    target === '/config/auto-analysis-rules.json'
      ? '，宿主机通常对应 config/worker/auto-analysis-rules.json'
      : '';
  const savedAt = result.savedAt ? `，保存时间 ${new Date(result.savedAt).toLocaleString('zh-CN', { hour12: false })}` : '';
  return `Worker 已写入 ${target}${hostHint}${savedAt}。`;
}

function isBuiltInScenarioId(id: string | undefined): boolean {
  return builtInAnalysisScenarios.some((scenario) => scenario.id === id);
}

function createUniqueScenarioId(prefix: string, scenarios: AnalysisScenario[]): string {
  const base = normalizeScenarioId(prefix) || 'custom';
  const existing = new Set([...builtInAnalysisScenarios, ...scenarios].map((scenario) => scenario.id));
  if (!existing.has(base)) {
    return base;
  }

  let index = 2;
  while (existing.has(`${base}-${index}`)) {
    index += 1;
  }
  return `${base}-${index}`;
}

function createUniqueRuleId(prefix: string, rules: AutoAnalysisRule[]): string {
  const base = normalizeScenarioId(prefix) || 'auto-rule';
  const existing = new Set(rules.map((rule) => rule.id));
  if (!existing.has(base)) {
    return base;
  }

  let index = 2;
  while (existing.has(`${base}-${index}`)) {
    index += 1;
  }
  return `${base}-${index}`;
}

function normalizeNumber(value: number | undefined, fallback: number): number {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function normalizeScenarioId(value: string): string {
  return value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9-]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80);
}

function createScenarioId(prefix = 'custom'): string {
  return `${normalizeScenarioId(prefix) || 'custom'}-${Date.now().toString(36)}`;
}

const panelBorder = '1px solid rgba(148, 163, 184, 0.3)';
const activeBorder = '1px solid rgba(96, 165, 250, 0.68)';
