import { getBackendSrv } from '@grafana/runtime';

export interface LogDataSource {
  uid: string;
  name: string;
  type: string;
  isDefault?: boolean;
}

export interface LokiFetchOptions {
  datasourceUid: string;
  query: string;
  minutes: number;
  limit: number;
  startMs?: number;
  endMs?: number;
}

export interface LokiCountOptions {
  datasourceUid: string;
  query: string;
  minutes: number;
  startMs?: number;
  endMs?: number;
}

export interface FetchedLogResult {
  text: string;
  totalLines: number;
}

export interface FetchedLogEntry {
  timestampNs: string;
  timestamp: string;
  text: string;
  labels: Record<string, string>;
  labelsText: string;
}

interface GrafanaDataSourceResponse {
  uid?: string;
  name?: string;
  type?: string;
  isDefault?: boolean;
}

interface LokiQueryRangeResponse {
  status?: string;
  data?: {
    result?: Array<{
      stream?: Record<string, string>;
      values?: Array<[string, string]>;
    }>;
  };
}

interface LokiInstantQueryResponse {
  status?: string;
  data?: {
    result?: Array<{
      value?: [number, string];
    }>;
  };
}

interface LokiLabelValuesResponse {
  status?: string;
  data?: string[];
}

interface LokiSeriesResponse {
  status?: string;
  data?: Array<Record<string, string>>;
}

interface LokiLogLine {
  timestampNs: string;
  text: string;
  labels: Record<string, string>;
}

export async function listLokiDataSources(): Promise<LogDataSource[]> {
  const dataSources = (await getBackendSrv().get('/api/datasources', undefined, undefined, {
    showSuccessAlert: false,
    showErrorAlert: false,
  })) as GrafanaDataSourceResponse[];

  return dataSources
    .filter((item) => item.uid && item.name && item.type === 'loki')
    .map((item) => ({
      uid: item.uid ?? '',
      name: item.name ?? '',
      type: item.type ?? '',
      isDefault: item.isDefault,
    }))
    .sort((left, right) => Number(Boolean(right.isDefault)) - Number(Boolean(left.isDefault)));
}


export async function listLokiLabelValues(datasourceUid: string, labelName: string): Promise<string[]> {
  if (!datasourceUid) {
    return [];
  }

  const url =
    `/api/datasources/proxy/uid/${encodeURIComponent(datasourceUid)}` +
    `/loki/api/v1/label/${encodeURIComponent(labelName)}/values`;
  const response = (await getBackendSrv().get(url, undefined, undefined, {
    showSuccessAlert: false,
    showErrorAlert: false,
  })) as LokiLabelValuesResponse;

  if (response.status && response.status !== 'success') {
    throw new Error(`Loki 标签读取失败：${response.status}`);
  }

  return Array.from(new Set(response.data ?? []))
    .filter(Boolean)
    .sort((left, right) => left.localeCompare(right));
}

export async function listLokiSeriesLabelSets(options: {
  datasourceUid: string;
  match: string;
  minutes: number;
  startMs?: number;
  endMs?: number;
}): Promise<Array<Record<string, string>>> {
  if (!options.datasourceUid || !options.match.trim()) {
    return [];
  }

  const nowMs = Date.now();
  const endMs = normalizeQueryTime(options.endMs, nowMs);
  const startMs = normalizeQueryTime(options.startMs, endMs - Math.max(1, options.minutes) * 60 * 1000);
  const safeStartMs = startMs >= endMs ? endMs - Math.max(1, options.minutes) * 60 * 1000 : startMs;
  const url =
    `/api/datasources/proxy/uid/${encodeURIComponent(options.datasourceUid)}` +
    `/loki/api/v1/series?match[]=${encodeURIComponent(options.match.trim())}` +
    `&start=${toLokiTimestampNs(safeStartMs)}&end=${toLokiTimestampNs(endMs)}`;

  const response = (await getBackendSrv().get(url, undefined, undefined, {
    showSuccessAlert: false,
    showErrorAlert: false,
  })) as LokiSeriesResponse;

  if (response.status && response.status !== 'success') {
    throw new Error(`Loki series 查询失败：${response.status}`);
  }

  return response.data ?? [];
}

export async function fetchLokiLogs(options: LokiFetchOptions): Promise<FetchedLogResult> {
  const entries = await fetchLokiLogEntries(options);
  const text = entries
    .map((line) => `[${line.timestamp}] ${line.labelsText} ${line.text}`)
    .join('\n');

  return {
    text,
    totalLines: entries.length,
  };
}

export async function fetchLokiLogEntries(options: LokiFetchOptions): Promise<FetchedLogEntry[]> {
  const query = options.query.trim();
  if (!options.datasourceUid) {
    throw new Error('请选择 Loki 数据源。');
  }
  if (!query) {
    throw new Error('请填写 LogQL 查询语句。');
  }

  const nowMs = Date.now();
  const endMs = normalizeQueryTime(options.endMs, nowMs);
  const startMs = normalizeQueryTime(options.startMs, endMs - Math.max(1, options.minutes) * 60 * 1000);
  const safeStartMs = startMs >= endMs ? endMs - Math.max(1, options.minutes) * 60 * 1000 : startMs;
  const end = toLokiTimestampNs(endMs);
  const start = toLokiTimestampNs(safeStartMs);
  const limit = Math.max(1, Math.min(options.limit || 300, 5000));
  const url =
    `/api/datasources/proxy/uid/${encodeURIComponent(options.datasourceUid)}` +
    `/loki/api/v1/query_range?query=${encodeURIComponent(query)}` +
    `&start=${start}&end=${end}&limit=${limit}&direction=BACKWARD`;

  const response = (await getBackendSrv().get(url, undefined, undefined, {
    showSuccessAlert: false,
    showErrorAlert: false,
  })) as LokiQueryRangeResponse;

  if (response.status && response.status !== 'success') {
    throw new Error(`Loki 查询失败：${response.status}`);
  }

  const lines = parseLokiLines(response);
  return lines.sort(compareLokiLine).map((line) => ({
    timestampNs: line.timestampNs,
    timestamp: formatLokiTimestamp(line.timestampNs),
    text: line.text,
    labels: line.labels,
    labelsText: formatLabels(line.labels),
  }));
}

export async function fetchLokiLogCount(options: LokiCountOptions): Promise<number> {
  const query = options.query.trim();
  if (!options.datasourceUid) {
    throw new Error('请选择 Loki 数据源。');
  }
  if (!query) {
    throw new Error('请填写 LogQL 查询语句。');
  }

  const nowMs = Date.now();
  const endMs = normalizeQueryTime(options.endMs, nowMs);
  const startMs = normalizeQueryTime(options.startMs, endMs - Math.max(1, options.minutes) * 60 * 1000);
  const safeStartMs = startMs >= endMs ? endMs - Math.max(1, options.minutes) * 60 * 1000 : startMs;
  const rangeSeconds = Math.max(1, Math.ceil((endMs - safeStartMs) / 1000));
  const countQuery = `sum(count_over_time(${query} [${rangeSeconds}s]))`;
  const url =
    `/api/datasources/proxy/uid/${encodeURIComponent(options.datasourceUid)}` +
    `/loki/api/v1/query?query=${encodeURIComponent(countQuery)}` +
    `&time=${toLokiTimestampNs(endMs)}`;

  const response = (await getBackendSrv().get(url, undefined, undefined, {
    showSuccessAlert: false,
    showErrorAlert: false,
  })) as LokiInstantQueryResponse;

  if (response.status && response.status !== 'success') {
    throw new Error(`Loki 计数查询失败：${response.status}`);
  }

  const value = Number(response.data?.result?.[0]?.value?.[1] ?? 0);
  return Number.isFinite(value) ? value : 0;
}

function parseLokiLines(response: LokiQueryRangeResponse): LokiLogLine[] {
  const result = response.data?.result ?? [];
  const lines: LokiLogLine[] = [];

  for (const stream of result) {
    for (const value of stream.values ?? []) {
      const [timestampNs, text] = value;
      lines.push({
        timestampNs,
        text,
        labels: stream.stream ?? {},
      });
    }
  }

  return lines;
}

function formatLabels(labels: Record<string, string> | undefined): string {
  const entries = Object.entries(labels ?? {});
  if (entries.length === 0) {
    return '';
  }

  return `{${entries.map(([key, value]) => `${key}="${value}"`).join(',')}} `;
}

function compareLokiLine(left: LokiLogLine, right: LokiLogLine): number {
  const leftNs = BigInt(left.timestampNs || '0');
  const rightNs = BigInt(right.timestampNs || '0');

  if (leftNs === rightNs) {
    return 0;
  }

  return leftNs > rightNs ? 1 : -1;
}

function formatLokiTimestamp(timestampNs: string): string {
  try {
    const timestampMs = Number(BigInt(timestampNs) / BigInt(1000000));
    return new Date(timestampMs).toISOString();
  } catch {
    return timestampNs;
  }
}

function toLokiTimestampNs(timestampMs: number): string {
  return (BigInt(timestampMs) * BigInt(1000000)).toString();
}

function normalizeQueryTime(value: number | undefined, fallback: number): number {
  if (!Number.isFinite(value)) {
    return fallback;
  }

  return Math.round(value as number);
}
