import * as React from 'react';
import { AppRootProps } from '@grafana/data';

import { AnalyzerPage } from '../pages/AnalyzerPage';
import { AboutPage } from '../pages/AboutPage';
import { HomePage } from '../pages/HomePage';
import { AlertConfigPage } from '../pages/AlertConfigPage';
import { AppConfig } from '../types';

export function App(props: AppRootProps<AppConfig>) {
  const path = window.location.pathname.toLowerCase();

  if (path.endsWith('/about') || path.includes('/page/about')) {
    return (
      <React.Fragment>
        <AboutPage />
      </React.Fragment>
    );
  }

  if (path.endsWith('/analyzer') || path.includes('/page/analyzer')) {
    return (
      <React.Fragment>
        <AnalyzerPage {...props} />
      </React.Fragment>
    );
  }

  if (path.endsWith('/alert-config') || path.includes('/page/alert-config')) {
    return (
      <React.Fragment>
        <AlertConfigPage {...props} />
      </React.Fragment>
    );
  }

  return (
    <React.Fragment>
      <HomePage {...props} />
    </React.Fragment>
  );
}
