import { LocalLogSummary, LogAnalyzerOptions, PatternCount } from '../types';

const riskyKeywords = [
  'fatal',
  'panic',
  'exception',
  'error',
  'failed',
  'timeout',
  'timed out',
  'refused',
  'reset by peer',
  'oom',
  'out of memory',
  'deadlock',
  'slow query',
  'too many connections',
  '429',
  '500',
  '502',
  '503',
  '504',
];

export function createLocalSummary(rawLogs: string, options: LogAnalyzerOptions): LocalLogSummary {
  const normalizedLogs = options.redact ? redactSensitiveData(rawLogs) : rawLogs;
  const lines = splitLines(normalizedLogs);
  const selected = lines.slice(0, Math.max(1, options.maxLines));
  const lowerLines = selected.map((line) => line.toLowerCase());

  const evidence = selected
    .filter((line, index) => riskyKeywords.some((keyword) => lowerLines[index].includes(keyword)))
    .slice(0, 80);

  return {
    totalLines: lines.length,
    selectedLines: selected.length,
    errorLines: countKeyword(lowerLines, 'error'),
    warnLines: countKeyword(lowerLines, 'warn'),
    fatalLines: countKeyword(lowerLines, 'fatal') + countKeyword(lowerLines, 'panic'),
    timeoutLines: countKeyword(lowerLines, 'timeout') + countKeyword(lowerLines, 'timed out'),
    topPatterns: groupPatterns(evidence.length ? evidence : selected),
    evidence,
    redactedLogs: selected.join('\n'),
  };
}

export function buildAnalysisPrompt(summary: LocalLogSummary, options: LogAnalyzerOptions): string {
  const scenario = options.analysisScenario;
  const service = options.serviceName || '未填写';
  const environment = options.environment || '未填写';
  const timeRange = options.timeRange || '未填写';
  const topPatterns = summary.topPatterns
    .map((item, index) => `${index + 1}. ${item.count} 次：${item.pattern}`)
    .join('\n');
  const evidence = summary.evidence.slice(0, 60).join('\n');

  return [
    '# 日志分析请求',
    '',
    '## 基本信息',
    `- 分析场景：${scenario.name}`,
    `- 场景说明：${scenario.description}`,
    `- 服务：${service}`,
    `- 环境：${environment}`,
    `- 时间范围：${timeRange}`,
    `- 原始日志行数：${summary.totalLines}`,
    `- 本次发送行数：${summary.selectedLines}`,
    `- 是否脱敏：${options.redact ? '是' : '否'}`,
    '',
    '## 本地统计',
    `- ERROR 行数：${summary.errorLines}`,
    `- WARN 行数：${summary.warnLines}`,
    `- FATAL/PANIC 行数：${summary.fatalLines}`,
    `- TIMEOUT 行数：${summary.timeoutLines}`,
    '',
    '## 场景化分析要求',
    '说明：分析场景不是日志格式约束，只用于调整关注重点。日志来源、字段和格式都可能变化，请以实际证据为准。',
    scenario.prompt,
    '',
    '## 高频异常模式',
    topPatterns || '暂无明显高频模式',
    '',
    '## 关键证据日志',
    '```text',
    evidence || summary.redactedLogs.slice(0, 12000) || '暂无日志',
    '```',
    '',
    '## 请输出',
    '请严格使用以下 Markdown 标题输出，便于页面结构化展示：',
    '',
    '## 故障等级',
    '- 等级：P0/P1/P2/P3/观察',
    '- 依据：用一句话说明为什么是这个等级。',
    '',
    '## 问题概述',
    '一句话说明最可能发生了什么。',
    '',
    '## 影响判断',
    '说明可能影响哪些服务、用户、链路或游戏功能。',
    '',
    '## 关键证据',
    '逐条引用上面日志中的证据，不要编造不存在的字段。',
    '',
    '## 可能根因',
    '按概率排序，不确定要标注。',
    '',
    '## 排查步骤',
    '给出可执行的命令、查询方向或验证点。',
    '',
    '## 临时处置',
    '止血、降级、扩容、回滚、补偿或限流建议。',
    '',
    '## 长期优化',
    '监控、告警、日志、容量、代码层面的建议。',
  ].join('\n');
}

export function redactSensitiveData(text: string): string {
  return text
    .replace(/(authorization:\s*bearer\s+)[^\s,;]+/gi, '$1<redacted-token>')
    .replace(/(x-api-key:\s*)[^\s,;]+/gi, '$1<redacted-api-key>')
    .replace(/(api[_-]?key["']?\s*[:=]\s*["']?)[^"',\s]+/gi, '$1<redacted-api-key>')
    .replace(/(password["']?\s*[:=]\s*["']?)[^"',\s]+/gi, '$1<redacted-password>')
    .replace(/(token["']?\s*[:=]\s*["']?)[^"',\s]+/gi, '$1<redacted-token>')
    .replace(/\bsk-[A-Za-z0-9_-]{12,}\b/g, '<redacted-sk-key>')
    .replace(/\b[A-Za-z0-9]{24,}\.[A-Za-z0-9_-]{12,}\b/g, '<redacted-provider-key>')
    .replace(/\b[\w.%+-]+@[\w.-]+\.[A-Za-z]{2,}\b/g, '<redacted-email>')
    .replace(/\b1[3-9]\d{9}\b/g, '<redacted-phone>')
    .replace(/\b(?:\d{1,3}\.){3}\d{1,3}\b/g, '<redacted-ip>');
}

function splitLines(text: string): string[] {
  return text
    .replace(/\r\n/g, '\n')
    .split('\n')
    .map((line) => line.trimEnd())
    .filter((line) => line.trim().length > 0);
}

function countKeyword(lines: string[], keyword: string): number {
  return lines.filter((line) => line.includes(keyword)).length;
}

function groupPatterns(lines: string[]): PatternCount[] {
  const bucket = new Map<string, PatternCount>();

  for (const line of lines) {
    const pattern = normalizePattern(line);
    const item = bucket.get(pattern) ?? { pattern, count: 0, samples: [] };
    item.count += 1;
    if (item.samples.length < 3) {
      item.samples.push(line);
    }
    bucket.set(pattern, item);
  }

  return Array.from(bucket.values())
    .sort((a, b) => b.count - a.count)
    .slice(0, 12);
}

function normalizePattern(line: string): string {
  return line
    .replace(/\d{4}-\d{2}-\d{2}[T\s]\d{2}:\d{2}:\d{2}(?:\.\d+)?(?:Z|[+-]\d{2}:\d{2})?/g, '<time>')
    .replace(/\b[0-9a-f]{8,}\b/gi, '<hex>')
    .replace(/\b\d+\b/g, '<num>')
    .replace(/\s+/g, ' ')
    .slice(0, 260);
}
